@IsTest
private class PlatformSignal52Test {
    private static List<String> names() {
        List<String> result = new List<String>();
        for(Account output : [SELECT Name FROM Account WHERE Name LIKE 'PFS-%' ORDER BY Name]) result.add(output.Name);
        return result;
    }
    @IsTest static void noEvents() {
        Test.getEventBus().deliver();
        System.assert(false, 'PFS-CELL:'+JSON.serialize(new Map<String,Object>{'case'=>'noEvents','names'=>names()}));
    }
    @IsTest static void oneEvent() {
        OwnedSignal__e signal = new OwnedSignal__e(Token__c='PFS-One');
        Database.SaveResult outcome=Eventbus.publish(signal);
        Map<String,Object> answer=new Map<String,Object>{'case'=>'oneEvent','published'=>outcome.isSuccess(),'callerToken'=>signal.Token__c,'before'=>names()};
        Test.getEventBus().deliver();
        answer.put('after',names());
        Test.getEventBus().deliver();
        answer.put('repeat',names());
        System.assert(false, 'PFS-CELL:'+JSON.serialize(answer));
    }
    @IsTest static void mixedEvents() {
        List<Database.SaveResult> outcomes=Eventbus.publish(new List<OwnedSignal__e>{new OwnedSignal__e(Token__c='PFS-Mixed'),new OwnedSignal__e()});
        List<Boolean> success=new List<Boolean>();
        for(Database.SaveResult outcome:outcomes) success.add(outcome.isSuccess());
        Map<String,Object> answer=new Map<String,Object>{'case'=>'mixedEvents','published'=>success,'before'=>names()};
        Test.getEventBus().deliver();
        answer.put('after',names());
        Test.getEventBus().deliver();
        answer.put('repeat',names());
        System.assert(false, 'PFS-CELL:'+JSON.serialize(answer));
    }
}

