public class PlatformSignalRecorder {
    @InvocableMethod(label='Capture owned signal')
    public static void capture(List<OwnedSignal__e> signals) {
        List<Account> outputs = new List<Account>();
        for (OwnedSignal__e signal : signals) {
            outputs.add(new Account(Name=signal.Token__c == null ? 'PFS-Empty' : signal.Token__c));
        }
        insert outputs;
    }
}
